def gen(rng):
    def fmt(a, k):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))

    tests = [fmt([1], 1), fmt([1, 1, 1], 2), fmt([1, 2, 3, 4], 3), fmt([1, 2, 1, 3], 2), fmt([4, 4, 4, 4], 1),
             fmt([1, 2, 3], 3), fmt([1, 2, 3], 2), fmt([7, 7], 2), fmt([1, 2, 1, 2, 1, 2], 3)]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for alpha in (2, 3, 6):
            a = [rng.randint(1, alpha) for _ in range(n)]
            tests.append(fmt(a, rng.randint(1, min(n, alpha + 1))))
    N = 100000
    tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(N)], 50000))
    tests.append(fmt([rng.randint(1, 300) for _ in range(N)], 150))
    tests.append(fmt([rng.randint(1, 2) for _ in range(N)], 2))
    tests.append(fmt([rng.randint(1, 50000) for _ in range(N)], 20000))
    tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(N)], 1))
    return tests
